            header.Length = (byte)data.Length;
            header.SubCode = SubCode;
        }
    }

    /// <summary>
    /// Gets the header type of this data packet.
    /// </summary>
    public static byte HeaderType => 0xC1;

    /// <summary>
    /// Gets the operation code of this data packet.
    /// </summary>
    public static byte Code => 0xEE;

    /// <summary>
    /// Gets the operation sub-code of this data packet.
    /// The <see cref="Code" /> is used as a grouping key.
    /// </summary>
    public static byte SubCode => 0x85;

    /// <summary>
    /// Gets the header of this packet.
    /// </summary>
    public C1HeaderWithSubCode Header => new (this._data);

    /// <summary>
    /// Gets or sets the pentagram slot.
    /// </summary>
    public byte PentagramSlot
    {
        get => this._data.Span[4];
        set => this._data.Span[4] = value;
    }

    /// <summary>
    /// Gets or sets the errtel count.
    /// </summary>
    public byte ErrtelCount
    {
        get => this._data.Span[5];
        set => this._data.Span[5] = value;
    }

    /// <summary>
    /// Gets the <see cref="SocketedErrtel"/> of the specified index.
    /// </summary>
        public SocketedErrtel this[int index] => new (this._data.Slice(6 + index * SocketedErrtel.Length));

    /// <summary>
    /// Performs an implicit conversion from a Memory of bytes to a <see cref="PentagramErrtels"/>.
    /// </summary>
    /// <param name="packet">The packet as span.</param>
    /// <returns>The packet as struct.</returns>
    public static implicit operator PentagramErrtels(Memory<byte> packet) => new (packet, false);

    /// <summary>
    /// Performs an implicit conversion from <see cref="PentagramErrtels"/> to a Memory of bytes.
    /// </summary>
    /// <param name="packet">The packet as struct.</param>
    /// <returns>The packet as byte span.</returns>
    public static implicit operator Memory<byte>(PentagramErrtels packet) => packet._data; 

    /// <summary>
    /// Calculates the size of the packet for the specified count of <see cref="SocketedErrtel"/>.
    /// </summary>
    /// <param name="errtelsCount">The count of <see cref="SocketedErrtel"/> from which the size will be calculated.</param>
        
    public static int GetRequiredSize(int errtelsCount) => errtelsCount * SocketedErrtel.Length + 6;
}
